// Reconciliation models for matching receipts with transactions

import type { ReceiptRow } from './Receipt';
import type { TransactionRow } from './Transaction';

/**
 * Confidence level assigned to a receipt/transaction match
 */
export type MatchConfidence = 'high' | 'medium' | 'low';

/**
 * Tolerances used by the matching algorithm when comparing receipts to transactions
 */
export type MatchingTolerances = {
	maxDaysDifference: number; // Max days between receipt and transaction dates
	amountTolerance: number; // Max absolute CAD difference for same-currency matches
	foreignCurrencyTolerancePercent: number; // #{#fcr3a} Max relative difference for converted amounts
};

/**
 * Single source of truth for the matching tolerance defaults
 */
export const DEFAULT_MATCHING_TOLERANCES: MatchingTolerances = {
	maxDaysDifference: 3,
	amountTolerance: 0.01, // 1 cent
	foreignCurrencyTolerancePercent: 0.05 // 5%
};

/**
 * Fills any missing tolerance overrides with the defaults
 */
export function resolveMatchingTolerances(
	overrides: Partial<MatchingTolerances>
): MatchingTolerances {
	return {
		maxDaysDifference: overrides.maxDaysDifference ?? DEFAULT_MATCHING_TOLERANCES.maxDaysDifference,
		amountTolerance: overrides.amountTolerance ?? DEFAULT_MATCHING_TOLERANCES.amountTolerance,
		foreignCurrencyTolerancePercent:
			overrides.foreignCurrencyTolerancePercent ??
			DEFAULT_MATCHING_TOLERANCES.foreignCurrencyTolerancePercent
	};
}

/**
 * Represents a matched pair of receipt and transaction
 */
export type MatchedPair = {
	receipt: ReceiptRow;
	transaction: TransactionRow;
	matchConfidence: MatchConfidence;
};

/**
 * Represents an unmatched receipt (no corresponding transaction found)
 */
export type UnmatchedReceipt = {
	receipt: ReceiptRow;
	potentialMatches: TransactionRow[];
};

/**
 * Represents an unmatched transaction (no corresponding receipt found)
 */
export type UnmatchedTransaction = {
	transaction: TransactionRow;
	potentialMatches: ReceiptRow[];
};

/**
 * Result of the reconciliation matching process
 */
export type ReconciliationResult = {
	matched: MatchedPair[];
	unmatchedReceipts: UnmatchedReceipt[];
	unmatchedTransactions: UnmatchedTransaction[];
	stats: ReconciliationStats;
};

/**
 * Statistics about the reconciliation
 */
export type ReconciliationStats = {
	totalReceipts: number;
	totalTransactions: number;
	matchedCount: number;
	unmatchedReceiptCount: number;
	unmatchedTransactionCount: number;
	matchRate: number; // Percentage of matched items
};

/**
 * Options for reconciliation matching
 */
export type ReconciliationOptions = {
	startDate: string; // ISO date string (YYYY-MM-DD)
	endDate: string; // ISO date string (YYYY-MM-DD)
	includeManuallMatched?: boolean; // Default: true
} & Partial<MatchingTolerances>; // Defaults: DEFAULT_MATCHING_TOLERANCES

/**
 * Sorting options for reconciliation display
 */
export type ReconciliationSortField = 'date' | 'vendor' | 'amount' | 'creditCard' | 'matchStatus';

export type ReconciliationSortDirection = 'asc' | 'desc';

export type ReconciliationSort = {
	field: ReconciliationSortField;
	direction: ReconciliationSortDirection;
};

/**
 * Display row for reconciliation table
 */
export type ReconciliationDisplayRow = {
	id: string; // Unique identifier for the row
	type: 'matched' | 'unmatchedReceipt' | 'unmatchedTransaction';
	receipt: ReceiptRow | null;
	transaction: TransactionRow | null;
	date: string | null;
	vendor: string | null;
	amount: number | null;
	creditCard: string | null;
	matchConfidence?: MatchConfidence;
	convertedAmountCAD: number | null; // #{#fcr5b} Estimated CAD amount for foreign currency receipts
};

/**
 * Manual match request
 */
export type ManualMatchRequest = {
	receiptId: string;
	transactionId: string;
};

/**
 * Manual unmatch request
 */
export type ManualUnmatchRequest = {
	receiptId: string;
};

